<?php admin_page_start('Support','support','SUPPORT DESK','Support','Tickets','User issues, diagnostics and conversations in one queue.'); $supportPageUrl=static function(int $target)use($status,$q):string{$params=['status'=>$status,'q'=>$q,'page'=>$target];$params=array_filter($params,static fn($v)=>$v!==''&&$v!=='all'&&$v!==1);return route_url('admin/support.php').($params?'?'.http_build_query($params):'');}; ?>
<section class="admin-stats"><article class="app-stat admin-stat stat-active"><div class="stat-label"><span class="stat-mark"></span>Open</div><strong><?=intval($stats['open']??0)?></strong><small>Needs attention</small></article><article class="app-stat admin-stat stat-warn"><div class="stat-label"><span class="stat-mark"></span>Waiting</div><strong><?=intval($stats['waiting']??0)?></strong><small>Waiting on user</small></article><article class="app-stat admin-stat"><div class="stat-label"><span class="stat-mark"></span>Closed</div><strong><?=intval($stats['closed']??0)?></strong><small>Resolved</small></article><article class="app-stat admin-stat"><div class="stat-label"><span class="stat-mark"></span>Total</div><strong><?=intval($total)?></strong><small>Filtered tickets</small></article></section>
<section class="app-panel admin-panel admin-card-pad"><div class="panel-heading"><div><p class="panel-kicker">TICKET QUEUE</p><h2>Support requests</h2></div><form method="get" class="admin-search"><input type="search" name="q" value="<?=htmlspecialchars($q,ENT_QUOTES,'UTF-8')?>" autocomplete="off" enterkeyhint="search" placeholder="User, subject, ticket #" aria-label="Search support tickets"><select name="status"><option value="all">All</option><?php foreach(['open','waiting','closed'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select><button class="app-button admin-button secondary" type="submit">Filter</button></form></div><div class="admin-table-wrap"><table class="app-table admin-table"><thead><tr><th>Ticket</th><th>User</th><th>Category</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if(!$tickets):?><tr><td colspan="6" class="empty-state">No tickets found.</td></tr><?php else:foreach($tickets as $t):?><tr><td><strong>#<?=(int)$t['id']?> · <?=htmlspecialchars((string)$t['subject'],ENT_QUOTES,'UTF-8')?></strong><?php if((int)($t['unread_count']??0)>0):?> <span class="app-badge support-unread-badge"><?=min(99,(int)$t['unread_count'])?> NEW</span><?php endif;?></td><td><?=htmlspecialchars((string)$t['username'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(strtoupper((string)$t['category']),ENT_QUOTES,'UTF-8')?></td><td><span class="app-badge status-pill status-<?=($t['status']==='closed'?'neutral':($t['status']==='waiting'?'warning':'active'))?>"><i></i><?=htmlspecialchars(strtoupper((string)$t['status']),ENT_QUOTES,'UTF-8')?></span></td><td><?=web_local_datetime($t['updated_at']??null,'—')?></td><td><a class="admin-table-link" href="<?=route_url('admin/support-ticket.php')?>?id=<?=(int)$t['id']?>">Open ↗</a></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($pages>1):?><nav class="admin-pagination" aria-label="Support ticket pages"><?php if($page>1):?><a href="<?=htmlspecialchars($supportPageUrl($page-1),ENT_QUOTES,'UTF-8')?>">← Previous</a><?php else:?><span class="is-disabled">← Previous</span><?php endif;?><strong>Page <?=$page?> / <?=$pages?></strong><?php if($page<$pages):?><a href="<?=htmlspecialchars($supportPageUrl($page+1),ENT_QUOTES,'UTF-8')?>">Next →</a><?php else:?><span class="is-disabled">Next →</span><?php endif;?></nav><?php endif;?></section>
<?php admin_page_end(); ?>
